const { query } = require("./db");

/**
 * Profile visibility rules, in one place.
 *
 * These are needed by at least six endpoints (profile, followers list, feed,
 * discover, search, diagram fetch). Duplicating the logic across them is how
 * a privacy leak happens: one endpoint gets updated, another doesn't, and a
 * private account's work quietly shows up in search. So every caller asks here.
 *
 * The rule:
 *   - A public profile is visible to everyone, signed in or not.
 *   - A private profile is visible to the owner, and to accepted followers.
 *   - Nobody else — including signed-out visitors — sees their content.
 */

/** @returns {'accepted'|'pending'|null} */
async function followStatus(viewerId, targetId) {
  if (!viewerId || !targetId) return null;
  const { rows } = await query(
    `SELECT status FROM follows WHERE follower_id = :viewerId AND following_id = :targetId`,
    { viewerId, targetId }
  );
  return rows.length ? rows[0].status : null;
}

async function isPrivate(userId) {
  const { rows } = await query(`SELECT is_private FROM users WHERE user_id = :userId`, { userId });
  if (!rows.length) return false;
  return Number(rows[0].is_private) === 1;
}

/**
 * Can `viewerId` (which may be null for a signed-out visitor) see `targetId`'s
 * profile and public diagrams?
 *
 * @returns {{visible: boolean, reason: string, private: boolean, followStatus: string|null}}
 */
async function canViewProfile(viewerId, targetId) {
  const priv = await isPrivate(targetId);
  if (!priv) return { visible: true, reason: "public", private: false, followStatus: viewerId ? await followStatus(viewerId, targetId) : null };
  if (viewerId && viewerId === targetId) return { visible: true, reason: "owner", private: true, followStatus: null };

  const status = await followStatus(viewerId, targetId);
  if (status === "accepted") return { visible: true, reason: "follower", private: true, followStatus: status };
  return { visible: false, reason: viewerId ? "not_a_follower" : "sign_in_required", private: true, followStatus: status };
}

/**
 * SQL fragment excluding private users' content from listings (feed, discover,
 * search) unless the viewer is the owner or an accepted follower. Written as a
 * fragment rather than a post-filter so the LIMIT applies to visible rows —
 * filtering after the query silently returns short pages.
 *
 * Requires the query to expose the author's id as `d.user_id`, and to bind
 * :viewerId (pass null when signed out).
 */
const VISIBLE_AUTHOR_SQL = `
  (
    COALESCE((SELECT u2.is_private FROM users u2 WHERE u2.user_id = d.user_id), FALSE) = FALSE
    OR d.user_id = :viewerId
    OR EXISTS (
      SELECT 1 FROM follows f2
      WHERE f2.follower_id = :viewerId AND f2.following_id = d.user_id AND f2.status = 'accepted'
    )
  )
`;

module.exports = { canViewProfile, followStatus, isPrivate, VISIBLE_AUTHOR_SQL };
